export const VERSION=1;
export function score(questions,answers,penalty=0){let correct=0,wrong=0;for(const q of questions){if(answers[q.id]===undefined)continue;if(answers[q.id]===q.answer)correct++;else wrong++;}return {correct,wrong,skipped:questions.length-correct-wrong,marks:Math.round((correct-wrong*penalty)*100)/100,accuracy:correct+wrong?Math.round(correct/(correct+wrong)*100):0};}
export function mastery(attempts,topic){const recent=attempts.filter(a=>a.topic===topic).slice(-10);return recent.length?Math.round(recent.filter(a=>a.correct).length/recent.length*100):0;}
export function filtered(topics,exam,search='',subject='all'){const term=search.trim().toLocaleLowerCase();return topics.filter(t=>(exam==='all'||t.exams.includes(exam))&&(subject==='all'||t.subject===subject)&&Object.values(t.title).some(s=>s.toLocaleLowerCase().includes(term)));}
export function shuffle(items,rng=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function remaining(deadline,now=Date.now()){return Math.max(0,Math.ceil((deadline-now)/1000));}
export function readState(storage){try{const d=JSON.parse(storage.getItem('aptitudelab-v1'));if(d?.version!==VERSION)return fresh();return {version:VERSION,locale:d.locale==='hi'?'hi':'en',exam:['all','ssc','banking','railways','insurance'].includes(d.exam)?d.exam:'all',lessons:Array.isArray(d.lessons)?d.lessons.filter(x=>typeof x==='string'):[],attempts:Array.isArray(d.attempts)?d.attempts.filter(a=>typeof a.topic==='string'&&typeof a.correct==='boolean'):[],sessions:Array.isArray(d.sessions)?d.sessions:[]};}catch{return fresh();}}
export function fresh(){return {version:VERSION,locale:'en',exam:'all',lessons:[],attempts:[],sessions:[]};}
